import {clone,uid,now,initial,openStore,writeStore,previousRestore,sources,dna,validateBackup,markdown} from './store.js';
const app=document.querySelector('#app'),dialog=document.querySelector('#dialog');
const seed=await fetch('./seed.json').then(r=>{if(!r.ok)throw Error('Library unavailable');return r.json()});
let state,saveTimer,toastTimer,saveQueue=Promise.resolve(),saveError=false,storageReady=false,pendingImport=null,dialogReturn=null,loadBlocked=false,rawRecovery=null;
let search='',category='All',archiveTab='Analyses',period=7;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl=u=>/^https?:\/\//i.test(u||'')?esc(u):'#';
const imageUrl=u=>/^data:image\/(png|jpeg|webp|gif);base64,/.test(u||'')?esc(u):'';
const split=v=>String(v||'').split(',').map(x=>x.trim()).filter(Boolean);
const icons={today:'M4 3h16v18H4z M8 7h8 M8 11h8 M8 15h4',library:'M3 4h7c1 0 2 1 2 2v15c0-2-2-3-4-3H3z M21 4h-7c-1 0-2 1-2 2 M21 4v14h-5c-2 0-4 1-4 3',analyze:'M8 3H3v5 M16 3h5v5 M3 16v5h5 M21 16v5h-5 M8 12a4 4 0 1 0 8 0a4 4 0 1 0-8 0',projects:'M3 7h18v14H3z M7 3h10v4',archive:'M5 3h14v18l-7-5-7 5z',settings:'M12 8a4 4 0 1 0 0 8a4 4 0 1 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',arrow:'M5 12h14 M14 7l5 5-5 5',external:'M14 3h7v7 M21 3L10 14 M10 4H4v16h16v-6',plus:'M12 4v16 M4 12h16',back:'M15 5l-7 7 7 7',close:'M5 5l14 14 M19 5L5 19',search:'M10 3a7 7 0 1 0 0 14a7 7 0 1 0 0-14 M15 15l6 6',photo:'M3 3h18v18H3z M3 17l6-6 4 4 3-3 5 5 M16 7h.01',star:'M12 3l3 6 6 1-4.5 4.5 1 6.5-5.5-3-5.5 3 1-6.5L3 10l6-1z',check:'M5 12l4 4L19 6'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]||icons.arrow}"/></svg>`;
const btn=(label,action,id='',cls='')=>`<button type="button" class="button ${cls}" data-action="${action}" data-id="${esc(id)}">${label}</button>`;
const link=(label,path,cls='')=>`<a class="button ${cls}" href="#/${path}">${label}</a>`;
const external=(s,label)=>`<a class="button" href="${safeUrl(s.url)}" target="_blank" rel="noopener noreferrer">${esc(label||'Open '+s.name)} ${icon('external')}</a>`;
const header=(title,sub='',action='',eyebrow='')=>`<header class="page-header"><div>${eyebrow?`<p class="eyebrow">${esc(eyebrow)}</p>`:''}<h1>${esc(title)}</h1>${sub?`<p>${esc(sub)}</p>`:''}</div>${action}</header>`;
const section=(title,body)=>`<section class="section"><h3>${title}</h3>${body}</section>`;
const empty=(title,body,action='')=>`<div class="empty"><h2>${title}</h2><p>${body}</p>${action}</div>`;
const selected=(a,b)=>a===b?' selected':'';
const field=(name,label,value='',type='text',required=false,help='')=>`<label class="field"><span>${esc(label)}${required?' *':''}</span>${help?`<small>${esc(help)}</small>`:''}${type==='textarea'?`<textarea name="${esc(name)}" ${required?'required':''}>${esc(value)}</textarea>`:`<input name="${esc(name)}" type="${type}" value="${esc(value)}" ${required?'required':''}>`}</label>`;
const select=(name,label,values,value,required=false)=>`<label class="field"><span>${esc(label)}</span><select name="${name}" ${required?'required':''}>${values.map(v=>{const [key,label]=Array.isArray(v)?v:[v,v];return `<option value="${esc(key)}"${selected(String(key),String(value))}>${esc(label)}</option>`}).join('')}</select></label>`;
const date=s=>new Date(s).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});
const all=(hidden=false)=>sources(state,seed,hidden);
const source=id=>all(true).find(s=>s.id===Number(id));
const analysis=id=>state.analyses.find(a=>a.id===id);
const project=id=>state.projects.find(p=>p.id===id);
const canonCount=()=>state.sourceCanonIDs.length+state.analysisCanonIDs.length;
const ordinal=()=>Math.floor((Date.UTC(new Date().getFullYear(),new Date().getMonth(),new Date().getDate())-Date.UTC(new Date().getFullYear(),0,0))/86400000);
const daily=()=>['Architecture','Cinema','Archviz'].map((cat,i)=>{const list=all().filter(s=>s.category===cat&&!s.customCategory);return list[(ordinal()+[0,3,7][i])%list.length]}).filter(Boolean);
const focus=()=>{const list=state.focusItems.length?state.focusItems:seed.focus;return list[(ordinal()-1)%list.length]};
const revisit=()=>state.analyses.filter(a=>a.imageData&&Date.now()-Date.parse(a.createdAt)>30*86400000).sort((a,b)=>Date.parse(a.createdAt)-Date.parse(b.createdAt))[0];
function toast(msg){const el=document.querySelector('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4000)}
function status(text,error=false){document.querySelectorAll('.save-status').forEach(el=>{el.textContent=text;el.classList.toggle('not-saved',error)})}
function persist(){status('Saving…');clearTimeout(saveTimer);saveTimer=setTimeout(()=>flush(),220)}
async function flush(previous){clearTimeout(saveTimer);saveTimer=null;if(loadBlocked){status('Recovery required',true);return false}const snap=clone(state);saveQueue=saveQueue.catch(()=>{}).then(()=>writeStore(snap,previous));try{await saveQueue;saveError=false;status('Saved on device');return true}catch(e){saveError=true;status('Not saved',true);toast(e.message?.startsWith('Another tab')?e.message:'Storage could not save. Export a backup now; your changes remain on this screen.');return false}}
function shell(content,active='Today',classes='page'){
 const nav=['Today','Library','Analyze','Projects','Archive'];
 document.body.dataset.theme=state.appearance==='Automatic'?(matchMedia('(prefers-color-scheme: dark)').matches?'Dark':'Light'):state.appearance;
 app.innerHTML=`<div class="topbar"><a class="brand" href="#/today">pedrapreta<span>Edu</span></a><nav class="desktop-nav" aria-label="Main navigation">${nav.map(n=>`<a class="${active===n?'active':''}" ${active===n?'aria-current="page"':''} href="#/${n.toLowerCase()}">${n}</a>`).join('')}</nav><div class="utility"><span class="save-status" role="status">${saveError?'Not saved':storageReady?'Saved on device':'Storage unavailable'}</span><a href="#/settings" class="icon-button" aria-label="Practice and settings">${icon('settings')}</a></div></div><main id="main" class="${classes}" tabindex="-1">${content}</main><nav class="mobile-nav" aria-label="Main navigation">${nav.map(n=>`<a class="${active===n?'active':''}" ${active===n?'aria-current="page"':''} href="#/${n.toLowerCase()}">${icon(n.toLowerCase())}<span>${n}</span></a>`).join('')}</nav>`;
 document.title=`${active} · pedrapretaEdu`;
}
function sourceRow(s){return `<a class="source-row" href="#/source/${s.id}">${s.coverImage?`<img class="source-stamp" src="${imageUrl(s.coverImage)}" alt="">`:`<span class="source-stamp" aria-hidden="true">${esc(s.name.split(/\s/).map(x=>x[0]).slice(0,2).join(''))}</span>`}<div class="grow"><div class="source-title">${esc(s.name)}</div><div class="source-meta">${esc(s.customCategory||s.category)}</div></div><span class="rating" aria-label="Editorial rating ${s.rating} of 5">${s.rating} / 5</span></a>`}
function analysisCard(a){return `<a class="analysis-card" href="#/entry/${a.id}">${a.imageData?`<img src="${imageUrl(a.imageData)}" alt="Reference for ${esc(a.title)}" loading="lazy">`:`<div class="paper-preview">${esc(a.principle||a.composition||'A study in deliberate looking.')}</div>`}<h3>${esc(a.title)}</h3><p class="meta">${esc(a.mode)} · ${date(a.createdAt)}</p></a>`}
function todayView(){
 const f=focus(),list=daily(),rv=revisit();const greeting=new Date().getHours()<12?'Good morning':new Date().getHours()<18?'Good afternoon':'Good evening';
 shell(`<section class="today-scene"><p class="today-date">${new Date().toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long'})}</p><div class="greeting">${greeting},<strong>${esc(state.profileName||'Arda')}.</strong></div><p class="quote">“Better images<br>make a better you.”</p><div class="scene-bottom"><span class="eyebrow">Today's focus</span><h1>${esc(f?.title||'Your next observation')}</h1><p>${esc(f?.prompt||'Add a Daily Focus to shape your practice.')}</p><a class="button primary session-start full" href="#/training">${state.drafts.training?'Continue Session':'Start Session'} ${icon('arrow')}</a></div></section><div class="today-side"><div><div class="row between"><span class="eyebrow">A practice of looking</span><span class="meta">${String(ordinal()).padStart(3,'0')} / 365</span></div><div class="spacer"></div><div class="row between"><h2>Today's session</h2><span class="meta">${list.length*10} min</span></div><div class="session-list">${list.map((s,i)=>`<a class="session-row" href="#/source/${s.id}"><span class="number">0${i+1}</span><div><span class="meta">${esc(s.customCategory||s.category)}</span><div class="name">${esc(s.name)}</div></div>${icon('external')}</a>`).join('')}</div>${!list.length?empty('Choose your sources','Keep Architecture, Cinema and Archviz sources active.',link('Open Library','library')):''}</div><div><span class="eyebrow">Carry this into your work</span><div class="spacer"></div><p class="focus-note">${esc(f?.principle||'Name the decision behind the image.')}</p>${link('Edit Daily Focus','focus','quiet')}</div><div><div class="metrics">${[[state.sessions.length,'Sessions'],[state.analyses.length,'Analyses'],[canonCount(),'Personal Canon']].map(([n,l])=>`<div><div class="metric-value">${n}</div><div class="metric-label">${l}</div></div>`).join('')}</div>${rv?link('Revisit '+esc(rv.title),'revisit/'+rv.id,'full'):link('Weekly Review '+icon('arrow'),'review','quiet')}</div>${backupDue()?`<div class="notice">Your weekly backup is due. ${link('Export backup','settings','quiet')}</div>`:''}</div>`,'Today','today');
}
function libraryView(){shell(`${header('Library','Curated resources for a sharper eye.',link(icon('plus')+' Add','source-edit/new'))}<div class="search">${icon('search')}<input type="search" id="library-search" aria-label="Search sources, studios, topics" placeholder="Search sources, studios, topics…" value="${esc(search)}"></div><div class="chips" aria-label="Categories">${['All',...new Set([...seed.categories,...state.customCategories.map(c=>c.name),...all().map(s=>s.customCategory||s.category)])].map(c=>btn(esc(c),'category',c,'chip'+(category===c?' active':''))).join('')}</div><div class="row between"><span id="result-count" class="eyebrow"></span>${link('Manage library','manage','quiet')}</div><div class="library-grid" id="source-results"></div>`,'Library');filterLibrary()}
function filterLibrary(){const found=all().filter(s=>(category==='All'||(s.customCategory||s.category)===category)&&[s.name,s.subtitle,s.why,s.personalNote,...s.tags,...s.lookFor].join(' ').toLowerCase().includes(search.toLowerCase()));document.querySelector('#source-results').innerHTML=found.length?found.map(sourceRow).join(''):empty('No matches','Try another source, category or visual idea.');document.querySelector('#result-count').textContent=`${found.length} sources`}
function sourceView(id){const s=source(id);if(!s)return missing('Source');shell(`${link(icon('back')+' Library','library','quiet')}<div class="source-mast"><div class="row between"><span class="eyebrow">${esc(s.customCategory||s.category)}</span>${link('Edit source','source-edit/'+id,'quiet')}</div>${s.coverImage?`<img class="source-cover" src="${imageUrl(s.coverImage)}" alt="${esc(s.name)} reference">`:''}<h1>${esc(s.name)}</h1><p class="muted">${esc(s.subtitle)}</p><div class="spacer"></div><div class="actions">${external(s)}${btn(icon('archive')+(state.savedSourceIDs.includes(s.id)?' Saved':' Save'),'save-source',id)}${btn(icon('star')+(state.sourceCanonIDs.includes(s.id)?' In Canon':' Canon'),'canon-source',id)}${btn('Add to Project','source-project',id)}</div></div><div class="detail-columns"><div>${section('Why study / Editorial Note',`<p class="pre">${esc(s.why)}</p>`)}${section('Look For',`<ul class="look-list">${s.lookFor.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`)}${section('Principle',`<p class="serif pre">${esc(s.takeaway)}</p>`)}</div><div>${section('Studio DNA',dna(s).map(t=>`<div class="dna-row"><span>${t.name}</span><span class="dna-track" role="img" aria-label="${t.score} of 5">${[1,2,3,4,5].map(n=>`<i class="${n<=t.score?'on':''}"></i>`).join('')}</span></div>`).join(''))}${section('My Note',`<label class="field"><span class="meta">Your own reading of this source · autosaved</span><textarea data-note-source="${s.id}" placeholder="What keeps bringing you back?">${esc(s.personalNote)}</textarea></label>${s.tags.length?`<p class="meta">${s.tags.map(esc).join(' · ')}</p>`:''}`)}${section('Study this source',`<div class="actions">${btn('Quick Study','start-study','Quick Study:'+s.id,'primary')}${btn('Deep Study','start-study','Deep Study:'+s.id)}</div>`)}</div></div>`,'Library')}
function genericDraft(key,base){if(!state.drafts[key])state.drafts[key]=clone(base);return state.drafts[key]}
function sourceEdit(id){const key='source-'+id;const original=id==='new'?{id:Math.max(1000,...all(true).map(s=>s.id))+1,name:'',category:'Archviz',customCategory:'',subtitle:'',url:'',rating:5,why:'',lookFor:[],takeaway:'',tags:[],personalNote:'',isCustom:true,artworkSeed:50}:source(id);if(!original)return missing('Source');const d=genericDraft(key,original);shell(`${header(id==='new'?'New source':'Edit source','Editorial and personal notes remain separate.',link('Close',id==='new'?'library':'source/'+id,'quiet'))}<form data-form="source" data-key="${key}" data-id="${id}">${field('name','Name',d.name,'text',true)}${field('url','Website URL',d.url,'url',true)}${field('subtitle','Subtitle',d.subtitle)}<div class="field-grid">${select('category','Category',seed.categories,d.category)}${select('customCategory','Custom category',[['','None'],...state.customCategories.map(c=>c.name)],d.customCategory||'')}</div>${select('rating','Editorial rating',[1,2,3,4,5],d.rating)}${field('why','Why Study / Editorial Note',d.why,'textarea')}${field('lookFor','Look For',Array.isArray(d.lookFor)?d.lookFor.join(', '):d.lookFor,'textarea',false,'Separate observations with commas.')}${field('takeaway','Principle',d.takeaway,'textarea')}${field('tags','Tags',Array.isArray(d.tags)?d.tags.join(', '):d.tags)}${field('personalNote','My Note',d.personalNote,'textarea')}<div class="image-upload">${d.coverImage?`<img src="${imageUrl(d.coverImage)}" alt="Source cover">`:''}<label class="field"><span>Your reference image (optional)</span><input type="file" accept="image/png,image/jpeg,image/webp" data-upload="coverImage" data-key="${key}"></label>${d.coverImage?btn('Remove image','remove-image',key+'|coverImage'):''}</div><div class="actions"><button class="button primary" type="submit">Save source</button>${btn('Discard draft','discard',key+'|'+(id==='new'?'library':'source/'+id))}</div></form>${id!=='new'?`<div class="section actions">${!original.isCustom?btn('Restore defaults','restore-source',id):''}${btn(original.isCustom?'Delete source':'Archive source','delete-source',id,'danger')}</div>`:''}`,'Library','page narrow')}
function analyzeView(){const templates=state.studyTemplates.filter(t=>['Quick Study','Deep Study'].includes(t.mode));const drafts=Object.entries(state.drafts).filter(([k])=>k.startsWith('study-'));shell(`${header('Analyze','Observe first. Name the mechanism second.',link('Form Builder','templates'))}${drafts.map(([k,d])=>`<div class="draft-row row between"><div><span class="meta">Unfinished study</span><h3>${esc(d.title||d.mode)}</h3></div><div class="actions">${link('Continue','study/'+k)}${btn('Discard','discard',k+'|analyze')}</div></div>`).join('')}<div class="study-grid"><div><span class="eyebrow">Study templates</span>${templates.map(t=>`<div class="study-row"><div><h2>${esc(t.name)}</h2><p>${t.fields.length} fields · ${t.mode==='Quick Study'?'One useful observation.':'Read the image as a system of decisions.'}</p></div>${btn(icon('arrow'),'start-template',t.id,'quiet')}</div>`).join('')}</div><div><span class="eyebrow">Exercises</span>${[['Compare','Two images. Same criteria. One explicit judgement.'],['Blind Study','Read an archived image before seeing your old interpretation.'],['Revisit','Return to a study with today’s eye.']].map(([m,detail])=>`<div class="study-row"><div><h2>${m}</h2><p>${detail}</p></div>${btn(icon('arrow'),'exercise',m,'quiet')}</div>`).join('')}<div class="section"><p class="serif muted">Do not save an image until you can explain why it deserves to survive in your archive.</p></div></div></div>`,'Analyze')}
function startStudy(mode,sourceID=null,templateID=null,original=null){
 let template=clone(state.studyTemplates.find(t=>t.id===templateID)||state.studyTemplates.find(t=>t.mode===mode)||seed.templates.find(t=>t.mode===mode)||seed.templates[0]);
 if(mode==='Revisit')template={id:uid(),name:'Revisit',mode,fields:['First impression now','What do you notice now?','Principle now'].map(title=>({id:uid(),title,prompt:'Write before revealing…',type:'Long Text',options:[],isRequired:false}))};
 const key='study-'+uid();state.drafts[key]={id:uid(),mode,title:mode==='Blind Study'?'Blind Study':mode==='Revisit'?'Revisit':source(sourceID)?.name|| (mode==='Compare'?'A / B Comparison':'Visual Study'),sourceID:sourceID?Number(sourceID):null,template,responses:{},imageData:original?.imageData||null,secondaryImageData:null,originalID:original?.id||null,revealed:false,startedAt:now()};persist();go('study/'+key)
}
function dynamicField(f,value){const name='response:'+f.id;const req=f.isRequired;let control;
 if(['Short Text','Long Text','Tags'].includes(f.type))return field(name,f.title,value,f.type==='Long Text'?'textarea':'text',req,f.prompt||(f.type==='Tags'?'Comma separated terms are fine.':''));
 const opts=f.type==='Rating 1–5'?['1','2','3','4','5']:f.type==='Yes / No'?['Yes','No']:f.options;
 const multiple=f.type==='Multiple Choice';const vals=String(value||'').split(' · ');
 control=`<div class="actions">${opts.map((o,i)=>`<label class="choice"><input type="${multiple?'checkbox':'radio'}" name="${name}" value="${esc(o)}" ${vals.includes(o)?'checked':''} ${req&&!multiple&&i===0?'required':''}>${esc(o)}</label>`).join('')}</div>`;
 return `<fieldset class="field"><legend>${esc(f.title)}${req?' *':''}</legend>${f.prompt?`<small>${esc(f.prompt)}</small>`:''}${control}</fieldset>`
}
function uploadBox(key,fieldName,label,d){return `<div class="image-upload">${d[fieldName]?`<img src="${imageUrl(d[fieldName])}" alt="${esc(label)} reference">`:`<div class="upload-empty">${icon('photo')}<span>${esc(label)}</span></div>`}<label class="field"><span>${d[fieldName]?'Change':'Choose'} image${d.mode==='Compare'?' *':''}</span><input type="file" accept="image/png,image/jpeg,image/webp" data-upload="${fieldName}" data-key="${key}"></label>${d[fieldName]?btn('Remove','remove-image',key+'|'+fieldName):''}</div>`}
function studyView(key){const d=state.drafts[key];if(!d)return missing('Draft');const blind=['Blind Study','Revisit'].includes(d.mode),old=analysis(d.originalID);shell(`${header(d.template.name,blind?'Commit to a new observation before revealing the old one.':d.mode==='Compare'?'Two images. Same criteria. One explicit judgement.':'Read the image as a system of decisions.',link('Close','analyze','quiet'))}<form data-form="study" data-key="${key}">${blind?`<img class="study-image" src="${imageUrl(d.imageData)}" alt="Unlabelled archived reference">`:d.mode==='Compare'?`<div class="compare-images">${uploadBox(key,'imageData','Image A',d)}${uploadBox(key,'secondaryImageData','Image B',d)}</div>`:uploadBox(key,'imageData','Reference image',d)}<div class="spacer"></div>${!blind?`${field('title','Study title',d.title,'text',true)}${select('sourceID','Source',[['','Unlinked reference'],...all().map(s=>[s.id,s.name])],d.sourceID||'')}`:''}${d.template.fields.map(f=>dynamicField(f,d.responses[f.id]||'')).join('')}${blind&&!d.revealed?btn(d.mode==='Blind Study'?'Reveal Old Analysis':'Compare With Old Analysis','reveal',key,'primary full'):''}${blind&&d.revealed?`<section class="note-box"><span class="eyebrow">Then / Now</span><h3>${esc(old?.title||'Original study removed')}</h3><p class="serif pre">${esc(old?.principle||old?.composition||'No earlier principle recorded.')}</p><p class="meta">${esc(old?.fieldResponses?.map(f=>f.title+': '+f.value).join(' · ')||'')}</p></section>`:''}${!blind||d.revealed?'<button type="submit" class="button primary full">Save Analysis</button>':''}<p class="footnote">Draft saved automatically on this device. Imported images are resized to 1800 px for a lighter archive.</p></form>`,'Analyze','page narrow')}
function archiveView(){let items=state.analyses;let body='';if(archiveTab==='Analyses')body=items.length?`<div class="analysis-grid">${items.map(analysisCard).join('')}</div>`:empty('Your archive starts with a decision.','Make your first study, then keep the observation worth returning to.',link('Start a study','analyze','primary'));
 if(archiveTab==='References')body=all().filter(s=>state.savedSourceIDs.includes(s.id)).map(sourceRow).join('')||empty('No saved references','Save a source from Library to return to it.',link('Open Library','library'));
 if(archiveTab==='Principles')body=items.filter(a=>a.principle).map(a=>`<a class="list-row" href="#/entry/${a.id}"><div><span class="meta">${esc(a.title)}</span><p class="serif pre">${esc(a.principle)}</p></div>${icon('arrow')}</a>`).join('')||empty('No principles yet','Extract one transferable idea from your next study.');
 if(archiveTab==='Personal Canon')body=`<div class="row between"><p class="serif">Keep fewer things.<br>Understand them better.</p><span class="meta">${canonCount()} / 50</span></div><div class="spacer"></div>${all(true).filter(s=>state.sourceCanonIDs.includes(s.id)).map(sourceRow).join('')}<div class="spacer"></div><div class="analysis-grid">${items.filter(a=>state.analysisCanonIDs.includes(a.id)).map(analysisCard).join('')}</div>`;
 if(archiveTab==='Visual Vocabulary')body=`<div class="row between"><span class="eyebrow">${state.vocabulary.length} terms</span>${btn('Add term','edit-vocab','new')}</div>${state.vocabulary.map(v=>`<div class="section"><div class="row between"><h3>${esc(v.title)}</h3><div class="actions">${btn('Edit','edit-vocab',v.id,'quiet')}${btn('Delete','delete-vocab',v.id,'quiet')}</div></div><p class="pre">${esc(v.definition)}</p>${v.note?`<p class="serif pre">${esc(v.note)}</p>`:''}<p class="meta">${v.related.map(esc).join(' · ')}</p></div>`).join('')}`;
 shell(`${header('Archive','Keep fewer things. Understand them better.',link('Weekly Review','review'))}<div class="chips">${['Analyses','References','Principles','Personal Canon','Visual Vocabulary'].map(t=>btn(t,'archive-tab',t,'chip'+(archiveTab===t?' active':''))).join('')}</div>${body}`,'Archive')}
