 'edit-analysis':id=>{const a=analysis(id),key='study-edit-'+id;const fields=(a.fieldResponses?.length?a.fieldResponses:Object.entries({Composition:a.composition,Depth:a.depth,Light:a.light,Lens:a.lens,Color:a.color,Material:a.material,'Human presence':a.humanPresence,Narrative:a.narrative,'What would I steal?':a.steal,Principle:a.principle,Tags:a.tags.join(', ')}).map(([title,value])=>({fieldID:uid(),title,value}))).map(f=>({id:f.fieldID,title:f.title,prompt:'',type:/tags/i.test(f.title)?'Tags':'Long Text',options:[],isRequired:false}));if(!state.drafts[key])state.drafts[key]={...clone(a),originalMode:a.mode,mode:a.mode==='Compare'?'Compare':'Deep Study',editingID:id,template:{name:'Edit study',fields},responses:Object.fromEntries(fields.map(f=>[f.id,a.fieldResponses?.find(r=>r.fieldID===f.id)?.value||({'Principle':a.principle,'Composition':a.composition,'Depth':a.depth,'Light':a.light,'Lens':a.lens,'Color':a.color,'Material':a.material,'Human presence':a.humanPresence,'Narrative':a.narrative,'What would I steal?':a.steal,'Tags':a.tags.join(', ')})[f.title]||'']))};persist();go('study/'+key)},
